<template>
  <div class="launch-section">
    <div ref="canvasHost" class="cube-canvas" aria-hidden="true"></div>
    <div class="hero-shade" aria-hidden="true"></div>
    <div class="hero-inner">
      <div class="hero-copy">
        <p class="availability"><span aria-hidden="true"></span> Seeking graphics & animation tools internships</p>
        <h1>Hello, I'm Ollie<span>.</span></h1>
        <p class="hero-description">I'm an artist and programmer building tools for painterly rendering and hand-drawn animation in 3D.</p>
        <div class="hero-actions">
          <a class="primary-action" href="#portfolio" @click.prevent="viewWork">View my work <span aria-hidden="true">↓</span></a>
          <a class="secondary-action" :href="resume" target="_blank" rel="noopener noreferrer">Résumé <span aria-hidden="true">↗</span></a>
        </div>
      </div>
      <div class="cube-caption">
        <button v-if="cubeReady" class="motion-toggle" type="button" :aria-pressed="paused" @click="toggleMotion">{{ paused ? 'Play cube' : 'Pause cube' }}</button>
        <a href="https://github.com/olliearrison/Cube/tree/main" target="_blank" rel="noopener noreferrer">Behind the cube <span aria-hidden="true">↗</span></a>
      </div>
    </div>
  </div>
</template>

<script>
import * as THREE from 'three';
import info from '../../info';
import { createFrameLoop } from '../../utils/frameLoop.mjs';
export default {
  name: 'LaunchSection',
  data() { return { resume: info.links.resume, paused: false, cubeReady: false }; },
  mounted() {
    const host = this.$refs.canvasHost;
    const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    this.paused = motion.matches;
    let renderer;
    try { renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true }); }
    catch { return; } // The introduction remains usable when WebGL is unavailable.
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x253052, 1);
    host.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(30, 1, 1, 5000);
    camera.position.z = 2350;
    const geometry = new THREE.BufferGeometry();
    const particles = window.matchMedia('(pointer: coarse)').matches ? 16000 : 28000;
    const positions = new Float32Array(particles * 3);
    const colors = new Float32Array(particles * 3);
    // A stable distribution avoids visual jumps when the component remounts.
    let seed = 2417;
    const random = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
    for (let i = 0; i < particles * 3; i++) {
      positions[i] = (random() - .5) * 650;
      colors[i] = positions[i] / 650 + .5;
    }
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    // Soft point coverage and order-independent blending prevent the hard,
    // depth-writing squares from popping as densely packed particles cross.
    const sprite = document.createElement('canvas');
    sprite.width = sprite.height = 64;
    const context = sprite.getContext('2d');
    const gradient = context.createRadialGradient(32, 32, 0, 32, 32, 32);
    gradient.addColorStop(0, 'rgba(255,255,255,1)');
    gradient.addColorStop(.35, 'rgba(255,255,255,.8)');
    gradient.addColorStop(1, 'rgba(255,255,255,0)');
    context.fillStyle = gradient;
    context.fillRect(0, 0, 64, 64);
    const texture = new THREE.CanvasTexture(sprite);
    texture.minFilter = texture.magFilter = THREE.LinearFilter;
    texture.generateMipmaps = false;
    const material = new THREE.PointsMaterial({
      size: 22, map: texture, vertexColors: true, transparent: true, opacity: .8,
      blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
    });
    const points = new THREE.Points(geometry, material);
    points.rotation.set(.35, .55, .1);
    scene.add(points);
    let visible = true;
    let width = 0;
    let height = 0;
    const mouse = new THREE.Vector2(-100, -100);
    const raycaster = new THREE.Raycaster();
    raycaster.params.Points.threshold = 15;
    let pointerMoved = false;
    const render = () => renderer.render(scene, camera);
    const loop = createFrameLoop((delta) => {
      points.rotation.x += delta * .08;
      points.rotation.y += delta * .14;
      if (pointerMoved) {
        raycaster.setFromCamera(mouse, camera);
        for (const hit of raycaster.intersectObject(points, false)) {
          for (let c = 0; c < 3; c++) colors[hit.index * 3 + c] = Math.min(1, colors[hit.index * 3 + c] + .035);
        }
        geometry.attributes.color.needsUpdate = true;
        pointerMoved = false;
      }
      render();
    });
    const updatePlayback = () => {
      loop.setRunning(!this.paused && visible && !document.hidden);
    };
    this.updatePlayback = updatePlayback;
    const resize = () => {
      const nextWidth = Math.round(host.clientWidth);
      const nextHeight = Math.round(host.clientHeight);
      if (!nextWidth || !nextHeight || (nextWidth === width && nextHeight === height)) return;
      width = nextWidth;
      height = nextHeight;
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height, false);
      points.position.x = width > 760 ? camera.aspect * 330 : 160;
      render();
    };
    const onPointerMove = (event) => {
      if (this.paused || event.pointerType === 'touch') return;
      const rect = host.getBoundingClientRect();
      mouse.set(((event.clientX - rect.left) / rect.width) * 2 - 1, -((event.clientY - rect.top) / rect.height) * 2 + 1);
      pointerMoved = true;
    };
    const onMotionChange = (event) => { this.paused = event.matches; updatePlayback(); };
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(host);
    const intersectionObserver = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; updatePlayback(); });
    intersectionObserver.observe(host);
    motion.addEventListener('change', onMotionChange);
    document.addEventListener('visibilitychange', updatePlayback);
    this.$el.addEventListener('pointermove', onPointerMove);
    resize();
    updatePlayback();
    this.cubeReady = true;
    this.disposeCube = () => {
      loop.dispose();
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      motion.removeEventListener('change', onMotionChange);
      document.removeEventListener('visibilitychange', updatePlayback);
      this.$el.removeEventListener('pointermove', onPointerMove);
      geometry.dispose();
      material.dispose();
      texture.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    };
  },
  beforeUnmount() { this.disposeCube?.(); },
  methods: {
    toggleMotion() { this.paused = !this.paused; this.updatePlayback?.(); },
    viewWork() {
      const section = document.getElementById('portfolio');
      section.focus({ preventScroll: true });
      section.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    },
  },
};
</script>

