<template>
  <div class="portfolio-site">
    <a class="skip-link" href="#portfolio" @click.prevent="scrollToSection('portfolio')">Skip to projects</a>
    <header ref="header" class="site-header" @keydown.esc="closeMenu(true)">
      <div class="header-inner">
        <a class="wordmark" href="#launch" @click.prevent="scrollToSection('launch')">Ollie<span>.</span></a>
        <nav class="desktop-nav" aria-label="Main navigation">
          <a v-for="item in navigation" :key="item.id" :href="`#${item.id}`" @click.prevent="scrollToSection(item.id)">{{ item.label }}</a>
        </nav>
        <div class="header-actions">
          <a class="resume-link" :href="links.resume" target="_blank" rel="noopener noreferrer">Résumé <span aria-hidden="true">↗</span></a>
          <button ref="menuButton" class="menu-toggle" type="button" :aria-expanded="menuOpen" aria-controls="mobile-navigation" @click="menuOpen = !menuOpen">
            {{ menuOpen ? 'Close' : 'Menu' }} <span aria-hidden="true">{{ menuOpen ? '×' : '+' }}</span>
          </button>
        </div>
      </div>
      <nav v-show="menuOpen" id="mobile-navigation" class="mobile-nav" aria-label="Mobile navigation">
        <a v-for="item in navigation" :key="item.id" :href="`#${item.id}`" @click.prevent="scrollToSection(item.id)">{{ item.label }}</a>
      </nav>
    </header>
    <main>
      <section id="launch" aria-label="Introduction"><LaunchSection /></section>
      <section id="portfolio" tabindex="-1" aria-labelledby="portfolio-heading"><PortfolioSection /></section>
      <section id="home" tabindex="-1" aria-label="About Ollie"><HomeSection /></section>
      <section id="about" tabindex="-1" aria-label="Education and experience"><AboutSection /></section>
      <section id="artwork" tabindex="-1" aria-label="Artwork"><ArtworkSection /></section>
      <section id="skills" tabindex="-1" aria-label="Skills"><SkillsSection /></section>
    </main>
    <footer class="site-footer">
      <div class="footer-inner">
        <div class="footer-copy"><span class="wordmark">Ollie<span>.</span></span><small>© {{ year }} Ollie Arrison</small></div>
        <div class="footer-links" aria-label="Get in touch">
          <a :href="links.linkedin" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a>
          <a :href="links.github" target="_blank" rel="noopener noreferrer">GitHub ↗</a>
          <a :href="links.resume" target="_blank" rel="noopener noreferrer">Résumé ↗</a>
          <a href="mailto:darrison@andrew.cmu.edu">Email me ↗</a>
        </div>
      </div>
    </footer>
  </div>
</template>

<script>
import LaunchSection from '../components/main/Launch.vue';
import HomeSection from '../components/main/Home.vue';
import AboutSection from '../components/main/About.vue';
import PortfolioSection from '../components/main/Portfolio.vue';
import SkillsSection from '../components/main/Skills.vue';
import ArtworkSection from '../components/main/Artwork.vue';
import info from '../info';

export default {
  name: 'HomePage',
  components: { LaunchSection, HomeSection, AboutSection, PortfolioSection, SkillsSection, ArtworkSection },
  data() {
    return {
      menuOpen: false,
      links: info.links,
      year: new Date().getFullYear(),
      navigation: [
        { id: 'portfolio', label: 'Portfolio' },
        { id: 'home', label: 'About' },
        { id: 'artwork', label: 'Artwork' },
        { id: 'skills', label: 'Skills' },
      ],
    };
  },
  mounted() {
    document.addEventListener('pointerdown', this.handleOutsideClick);
    this.desktopQuery = window.matchMedia('(min-width: 761px)');
    this.desktopQuery.addEventListener('change', this.handleDesktopChange);
  },
  beforeUnmount() {
    document.removeEventListener('pointerdown', this.handleOutsideClick);
    this.desktopQuery.removeEventListener('change', this.handleDesktopChange);
  },
  methods: {
    closeMenu(returnFocus = false) {
      this.menuOpen = false;
      if (returnFocus) this.$refs.menuButton.focus();
    },
    handleOutsideClick(event) {
      if (!this.$refs.header.contains(event.target)) this.closeMenu();
    },
    handleDesktopChange(event) {
      if (event.matches) this.closeMenu();
    },
    scrollToSection(id) {
      this.closeMenu();
      const section = document.getElementById(id);
      if (!section) return;
      section.focus({ preventScroll: true });
      section.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
    },
  },
};
</script>

<style scoped>
