.desktop-nav a, .resume-link, .footer-links a { font-size: 14px; font-weight: 600; color: #414558; text-decoration: none; padding-block: 12px; }
.desktop-nav a:hover, .footer-links a:hover { color: #46579d; text-decoration: underline; text-underline-offset: 5px; }
