  .desktop-nav { display: none; }
  .header-actions { gap: 16px; }
  .menu-toggle { display: inline-flex; }
  .mobile-nav { display: grid; padding: 8px 20px 20px; border-top: 1px solid #e2e3e8; }
  .mobile-nav a { text-align: left; color: #212438; text-decoration: none; padding: 13px 8px; border-bottom: 1px solid #e2e3e8; }
  .footer-inner { align-items: flex-start; flex-direction: column; }
  .footer-links { gap: 12px 24px; }
}
</style>
